% ============================================================
% config.tex - CENTRALIZED CUSTOMISATION SETTINGS
% ------------------------------------------------------------
% Edit everything paper-specific here. Nothing else should need
% to change from paper to paper (except the candidate number,
% which is filled in by hand, and the questions in questions/).
% ============================================================

% ---- Paper metadata (corner strip, footer, running heads) ----
\newcommand{\PaperYear}{2023}
\newcommand{\PaperCode}{2023-DSE}
\newcommand{\PaperSubjLine}{PHY}
\newcommand{\PaperType}{PAPER 1B}
\newcommand{\PaperTotalMarks}{65}
\newcommand{\PaperTime}{2 hours 15 minutes}

% Code printed in the bottom-left of every page.
\newcommand{\PaperFooterCode}{2023-DSE-PHY1B-1}

% ---- Cover page text ----
\newcommand{\CoverAuthority}{HONG KONG EXAMINATIONS AND ASSESSMENT AUTHORITY}
\newcommand{\CoverExamName}{HONG KONG DIPLOMA OF SECONDARY EDUCATION EXAMINATION 2023}
\newcommand{\CoverTitle}{PHYSICS PAPER 1}
\newcommand{\CoverSubtitle}{SECTION B: Question-Answer Book B}
\newcommand{\CoverLanguageNote}{This paper must be answered in English}

% ---- Cover page instructions ----
\newcommand{\CoverInstrHeading}{INSTRUCTIONS FOR SECTION B}
% Pages on which barcode labels are stuck (used in instruction 1).
\newcommand{\CoverBarcodePages}{1, 3, 5, 7, and 9}
% The full instruction list. Edit the wording of any item here.
\newcommand{\CoverInstructions}{%
  \begin{enumerate}[label={(\arabic*)},itemsep=12pt,topsep=0pt,parsep=0pt,labelsep=1.6em]
    \item After the annoucement of the start of the examination, you should first write your Candidate Number in the space provided on Page 1 and stick barcode labels in the spaces provided on Pages \CoverBarcodePages.
    \item Refer to the general instructions on the cover of the Question Paper for Section A.
    \item Answer \textbf{ALL} questions.
